package org.json;import java.util.*;public class JSONArray{final List<Object> list;JSONArray(List<Object> l){list=l;}public JSONArray(String s)throws JSONException{list=((JSONArray)new JSON(s).value()).list;}public int length(){return list.size();}public Object get(int i)throws JSONException{return list.get(i);}public String getString(int i)throws JSONException{Object o=get(i);if(!(o instanceof String))throw new JSONException("not string");return (String)o;}public JSONObject getJSONObject(int i)throws JSONException{Object o=get(i);if(!(o instanceof JSONObject))throw new JSONException("not object");return (JSONObject)o;}public JSONObject optJSONObject(int i){Object o=list.get(i);return o instanceof JSONObject?(JSONObject)o:null;}public String optString(int i,String d){Object o=list.get(i);return o instanceof String?(String)o:d;}}